'use strict';

/**
 * AI-artifact detector for project documentation.
 *
 * Per v0.3 requirement 9.2: generated documents must not cite markdown that
 * was itself written by an LLM. Files such as TECHNICAL_SPECIFICATION.md,
 * ARCHITECTURE_GUIDELINES.md, and similar "generated" summaries commonly
 * appear in repositories and carry AI fingerprints that must not be
 * reproduced in formal documentation.
 *
 * Heuristics (combined to produce a confidence level):
 *   - Filename patterns often used for auto-generated specs
 *   - Known co-author / generator footer lines
 *   - Characteristic AI phrasing at the top of the file
 *
 * Return shape always includes `reasons[]` so callers can surface the
 * decision to the user.
 *
 * Pure module — no I/O. The caller supplies path + content.
 */

const SUSPICIOUS_FILENAME_PATTERNS = [
  /TECHNICAL_SPECIFICATION\.md$/i,
  /ARCHITECTURE_GUIDELINES\.md$/i,
  /AI_NOTES\.md$/i,
  /CLAUDE_NOTES\.md$/i,
  /GENERATED.*\.md$/i,
  /_AI_\.md$/i,
  /\bai-generated\b/i,
];

const FOOTER_PATTERNS = [
  /generated with \[?claude code\]?/i,
  /🤖 Generated with \[Claude Code\]/i,
  /co-authored-by:\s*claude/i,
  /anthropic claude/i,
  /generated by chatgpt/i,
  /generated by gpt-4/i,
  /produced by an ai assistant/i,
];

const PHRASING_PATTERNS = [
  /^#\s+(comprehensive|complete|thorough)\s+(guide|overview|documentation)/im,
  /this (document|guide) (provides|outlines|presents)/i,
  /let me (explain|walk you through|break down)/i,
  /here'?s a (comprehensive|complete|thorough)/i,
  /key (takeaways|points):$/im,
  /^as an ai/im,
];

function matchPatterns(value, patterns) {
  const matched = [];
  for (const re of patterns) {
    if (re.test(value)) matched.push(String(re));
  }
  return matched;
}

/**
 * @param {string} filePath
 * @param {string} content
 * @returns {{ is_ai_artifact: boolean, confidence: 'high'|'medium'|'low'|'none', reasons: string[] }}
 */
function detect(filePath, content) {
  const reasons = [];
  const body = typeof content === 'string' ? content : '';
  const name = String(filePath || '');

  const filenameHits = matchPatterns(name, SUSPICIOUS_FILENAME_PATTERNS);
  const footerHits = matchPatterns(body, FOOTER_PATTERNS);
  const phrasingHits = matchPatterns(body, PHRASING_PATTERNS);

  for (const hit of filenameHits) reasons.push(`filename matches ${hit}`);
  for (const hit of footerHits) reasons.push(`footer matches ${hit}`);
  for (const hit of phrasingHits) reasons.push(`phrasing matches ${hit}`);

  let confidence = 'none';
  if (footerHits.length > 0) confidence = 'high';
  else if (filenameHits.length > 0 && phrasingHits.length > 0) confidence = 'high';
  else if (filenameHits.length > 0) confidence = 'medium';
  else if (phrasingHits.length >= 2) confidence = 'medium';
  else if (phrasingHits.length === 1) confidence = 'low';

  return {
    is_ai_artifact: confidence === 'high' || confidence === 'medium',
    confidence,
    reasons,
  };
}

/**
 * Filter a list of markdown sources, separating AI-artifact candidates.
 *
 * @param {Array<{ path: string, content: string }>} sources
 * @returns {{ human: typeof sources, ai: Array<{ path: string, content: string, detection: ReturnType<typeof detect> }> }}
 */
function partition(sources) {
  const human = [];
  const ai = [];
  for (const src of sources || []) {
    const detection = detect(src.path, src.content);
    if (detection.is_ai_artifact) {
      ai.push({ ...src, detection });
    } else {
      human.push(src);
    }
  }
  return { human, ai };
}

module.exports = {
  detect,
  partition,
  SUSPICIOUS_FILENAME_PATTERNS,
  FOOTER_PATTERNS,
  PHRASING_PATTERNS,
};
